Complete local C++ example; the app itself does not execute it:
```cpp
#include <array>
#include <iostream>
#include <string_view>
struct Game { int score = 0; int turns = 2; bool playing = true; };
Game apply(Game state, std::string_view command) {
    if (!state.playing) return state;
    if (command == "quit") { state.playing = false; return state; }
    if (command != "collect") return state;
    ++state.score;
    --state.turns;
    if (state.turns == 0) state.playing = false;
    return state;
}
int main() {
    Game game;
    const std::array<std::string_view, 3> commands{"collect", "collect", "collect"};
    for (auto command : commands) game = apply(game, command);
    std::cout << game.score << " " << game.turns << " " << game.playing << "\n";
}
```

